'use strict';

/**
* LAPACK routine to compute a QR factorization of a real M-by-N matrix `A`.
*
* @module @stdlib/lapack/base/dgeqrf
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dgeqrf = require( '@stdlib/lapack/base/dgeqrf' );
*
* var A = new Float64Array( [ 1, 5, 9, 2, 6, 10, 3, 7, 11, 4, 8, 12 ] );
* var TAU = new Float64Array( 3 );
* var WORK = new Float64Array( 4 );
*
* dgeqrf( 'column-major', 3, 4, A, 3, TAU, WORK, 4 );
* // A => <Float64Array>[ ~-10.344, ~0.441, ~0.793, ~-11.794, ~0.947, ~0.919, ~-13.244, ~1.894, ~0.0, ~-14.694, ~2.842, ~0.0 ]
* // TAU => <Float64Array>[ ~1.097, ~1.084, 0.0 ]
* // WORK => <Float64Array>[ 4.0, ~-2.842, ~17.046, 0.0 ]
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dgeqrf;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dgeqrf = main;
} else {
	dgeqrf = tmp;
}


// EXPORTS //

module.exports = dgeqrf;

// exports: { "ndarray": "dgeqrf.ndarray" }
